Here's an Express endpoint for saving avatar uploads:

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const app = express();

// Configure storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = path.join(__dirname, 'uploads', 'avatars');
    fs.mkdirSync(uploadDir, { recursive: true });
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    // Save as: userId_timestamp.ext
    const ext = path.extname(file.originalname);
    const name = `${req.user?.id || 'user'}_${Date.now()}${ext}`;
    cb(null, name);
  }
});

// File filter - only images
const fileFilter = (req, file, cb) => {
  const allowedMimes = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
  if (allowedMimes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only image files are allowed'));
  }
};

const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB max
});

// Upload endpoint
app.post('/avatar', upload.single('avatar'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  res.json({
    success: true,
    filename: req.file.filename,
    path: `/uploads/avatars/${req.file.filename}`,
    size: req.file.size
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    if (err.code === 'LIMIT_FILE_SIZE') {
      return res.status(400).json({ error: 'File too large (max 5MB)' });
    }
  }
  if (err.message) {
    return res.status(400).json({ error: err.message });
  }
  res.status(500).json({ error: 'Upload failed' });
});

// Serve uploaded files
app.use('/uploads', express.static(path.join(__dirname, 'uploads')));

app.listen(3000, () => console.log('Server on port 3000'));
```

**Key features:**
- **Multer middleware** handles multipart form uploads
- **Disk storage** saves files to `uploads/avatars/` with unique names (userId_timestamp)
- **File filter** validates MIME types (jpeg, png, webp, gif)
- **Size limit** caps at 5MB
- **Error handling** catches multer errors and invalid files
- **Static serving** exposes the uploads directory at `/uploads`

**Usage:** POST to `/avatar` with form-data field named `avatar`. Returns filename and serving path.

Need to install: `npm install multer`
